mapper.select:
SELECT l.id, l.plate_no AS plateNo, l.enter_time AS enterTime, l.leave_time AS leaveTime, l.park_duration AS parkDuration, l.status, l.station_id AS stationId, s.name AS stationName, l.remark, l.proof_image AS proofImage, l.is_corrected AS isCorrected, l.reserve1, l.reserve2, l.creator, l.updater, l.create_time AS createTime, l.update_time AS updateTime FROM leave_record l LEFT JOIN station_info s ON l.station_id = s.id AND s.deleted = 0 WHERE l.deleted = 0
AND l.plate_no LIKE CONCAT('%', #{reqVO.plateNo}, '%')
AND l.enter_time BETWEEN FROM_UNIXTIME(#{reqVO.enterTime[0]}) AND FROM_UNIXTIME(#{reqVO.enterTime[1]})
AND l.leave_time BETWEEN FROM_UNIXTIME(#{reqVO.leaveTime[0]}) AND FROM_UNIXTIME(#{reqVO.leaveTime[1]})
AND DATE_FORMAT(l.leave_time, '%H:00') = #{reqVO.leaveTimeHour}
AND l.park_duration = #{reqVO.parkDuration}
AND l.status = #{reqVO.status}
AND l.station_id = #{reqVO.stationId}
AND s.name LIKE CONCAT('%', #{reqVO.stationName}, '%')
AND l.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
AND l.proof_image LIKE CONCAT('%', #{reqVO.proofImage}, '%')
AND l.is_corrected = #{reqVO.isCorrected}
ORDER BY l.id DESC
